settings.liquid:
{%- comment -%} Buy more, save more – change the collection handle, title or badge below {%- endcomment -%}
{%- assign up_collection = collections['copper-bracelets'] -%}
{%- assign up_title = 'Buy more, Save more' -%}
{%- assign up_badge = '50% OFF' -%}
{%- assign up_per_page = 3 -%}
<div class="sup" data-sup>
  <div class="sup__head">
    <p class="sup__title">{{ up_title }}</p>
    {%- if up_badge != blank -%}<span class="sup__badge">{{ up_badge }}</span>{%- endif -%}
    <div class="sup__nav">
      <button type="button" class="sup__arrow" data-sup-prev aria-label="Previous"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 3L5 8l5 5"/></svg></button>
      <button type="button" class="sup__arrow" data-sup-next aria-label="Next"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 3l5 5-5 5"/></svg></button>
    </div>
  </div>
  <ul class="sup__list">
    {%- assign shown = 0 -%}
    {%- for p in up_collection.products limit: 30 -%}
      {%- if p.id != product.id and p.available -%}
        {%- assign v = p.selected_or_first_available_variant -%}
        <li class="sup__item" data-sup-item>
          <a class="sup__img" href="{{ p.url }}">{%- if p.featured_image -%}{{ p.featured_image | image_url: width: 160, height: 160, crop: 'center' | image_tag: loading: 'lazy', alt: p.title }}{%- endif -%}</a>
          <div class="sup__info">
            <a class="sup__name" href="{{ p.url }}">{{ p.title }}</a>
            <p class="sup__prices"><span class="sup__price">{{ v.price | money }}</span>{%- if v.compare_at_price > v.price -%}<s class="sup__compare">{{ v.compare_at_price | money }}</s>{%- endif -%}</p>
          </div>
          {%- if p.has_only_default_variant -%}
            <button type="button" class="sup__add" data-sup-add="{{ v.id }}">+ Add</button>
          {%- else -%}
            <a class="sup__add" href="{{ p.url }}">+ Add</a>
          {%- endif -%}
        </li>
        {%- assign shown = shown | plus: 1 -%}
      {%- endif -%}
    {%- endfor -%}
  </ul>
</div>
<style>
  .sup { margin-top: 18px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial, sans-serif; }
  .sup__head { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
  .sup__title { margin: 0; font-size: 17px; font-weight: 700; color: #1a1a1a; }
  .sup__badge { background: #7a5434; color: #fff; font-size: 11.5px; font-weight: 700; letter-spacing: .04em; padding: 5px 9px; border-radius: 3px; white-space: nowrap; }
  .sup__nav { margin-left: auto; display: flex; gap: 6px; }
  .sup__arrow { width: 30px; height: 30px; border-radius: 50%; border: 1px solid #d9d3c9; background: #fff; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; color: #1a1a1a; padding: 0; }
  .sup__arrow svg { width: 14px; height: 14px; }
  .sup__arrow[disabled] { opacity: .35; cursor: default; }
  .sup__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
  .sup__item { display: grid; grid-template-columns: 64px 1fr auto; align-items: center; gap: 14px; padding: 10px 12px; background: rgba(255,255,255,.55); border: 1px solid #e2ddd4; border-radius: 8px; }
  .sup__item[hidden] { display: none; }
  .sup__img { display: block; width: 64px; height: 64px; border-radius: 6px; overflow: hidden; background: #eee; }
  .sup__img img { width: 100%; height: 100%; object-fit: cover; display: block; }
  .sup__name { display: block; font-size: 13.5px; font-weight: 600; color: #1a1a1a; text-decoration: none; line-height: 1.3; }
  .sup__prices { margin: 6px 0 0; display: flex; gap: 8px; align-items: baseline; font-size: 14px; }
  .sup__price { color: #3c8a4e; font-weight: 700; }
  .sup__compare { color: #c0392b; font-size: 13px; }
  .sup__add { background: #1a1a1a; color: #fff !important; border: 0; border-radius: 6px; padding: 10px 14px; font-size: 13px; font-weight: 700; cursor: pointer; text-decoration: none; white-space: nowrap; font-family: inherit; }
  .sup__add[aria-busy="true"] { opacity: .6; }
</style>
<script>
  (function () {
    var root = document.currentScript && document.currentScript.previousElementSibling && document.currentScript.previousElementSibling.previousElementSibling;
    if (!root || !root.matches('[data-sup]')) root = document.querySelector('[data-sup]');
    if (!root) return;
    var items = Array.prototype.slice.call(root.querySelectorAll('[data-sup-item]'));
    var per = {{ up_per_page }};
    var page = 0;
    var pages = Math.max(1, Math.ceil(items.length / per));
    var prev = root.querySelector('[data-sup-prev]');
    var next = root.querySelector('[data-sup-next]');
    function render() {
      items.forEach(function (el, i) { el.hidden = Math.floor(i / per) !== page; });
      prev.disabled = page === 0;
      next.disabled = page >= pages - 1;
    }
    prev.addEventListener('click', function () { if (page > 0) { page--; render(); } });
    next.addEventListener('click', function () { if (page < pages - 1) { page++; render(); } });
    if (pages < 2) root.querySelector('.sup__nav').style.display = 'none';
    render();

    root.addEventListener('click', function (e) {
      var btn = e.target.closest('button[data-sup-add]');
      if (!btn) return;
      btn.setAttribute('aria-busy', 'true');
      fetch('/cart/add.js', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({ items: [{ id: Number(btn.getAttribute('data-sup-add')), quantity: 1 }] })
      }).then(function (r) {
        if (!r.ok) throw new Error('add failed');
        btn.textContent = 'Added';
        if (typeof window.upcartRefreshCart === 'function') { window.upcartRefreshCart(); }
        if (typeof window.upcartOpenCart === 'function') { window.upcartOpenCart(); }
        else {
          var toggle = document.querySelector('[data-cart-toggle]');
          if (toggle) toggle.click();
        }
      }).catch(function () {
        window.location.href = '/cart';
      }).finally(function () { btn.removeAttribute('aria-busy'); });
    });
  })();
</script>
